class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        List<Integer> arr = new ArrayList<>();
        int m = Math.max(nums1.length, nums2.length);
        for (int i = 0; i < m; i++) {
            if (i < nums1.length)
                arr.add(nums1[i]);
            if (i < nums2.length)
                arr.add(nums2[i]);
        }
        Collections.sort(arr);
        int k = arr.size();
        if(k%2==1)
        {
            return arr.get(k/2);
        }
        else
        {
            double a = arr.get(k/2);
            double b = arr.get(k/2-1);
            return (a+b)/2;
        }
    }
}
